INSERT INTO HUNTTECH_AI_FUNCTION_CONFIGURATION ( ID, VERSION, CREATE_TS, CREATED_BY, CODE, NAME, DESCRIPTION, CAPABILITY, SYSTEM_PROMPT, PROMPT_TEMPLATE, TEMPERATURE, MAX_TOKENS, EXECUTION_POLICY, FALLBACK_POLICY, ALLOW_MODEL_OVERRIDE, IS_ACTIVE, CONFIGURATION_VERSION ) SELECT '5656f588-34aa-42ab-a72c-969f094df85e'::uuid, 1, CURRENT_TIMESTAMP, 'migration', 'PROJECT_SHORT_DESCRIPTION_GENERATE', 'Краткое описание проекта', 'Генерация краткого описания сути проекта (одно предложение) из полного описания по кнопке «Кратко» во вкладке «Описание проекта» ProjectEdit; выводится в sidebar-разделе «Коротко»', 'TEXT_GENERATION', 'Ты — ассистент HRM HuntTech. На основе полного описания проекта сформулируй краткое описание его сути: не более 1 предложения. Отрази главную цель проекта и предметную область. Не выдумывай фактов, которых нет в исходном тексте. Верни только итоговый обычный текст без Markdown, HTML и вступительных фраз.', E'Наименование проекта: ${projectName}

Полное описание проекта:
${sourceText}', 0.3, 125, 'USER_OVERRIDE_ALLOWED', 'FALLBACK_TO_ADMIN', FALSE, TRUE, 1 WHERE NOT EXISTS ( SELECT 1 FROM HUNTTECH_AI_FUNCTION_CONFIGURATION WHERE CODE = 'PROJECT_SHORT_DESCRIPTION_GENERATE' );
